readFirst values: [Int] -> Int => values[0]

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    values -> readFirst => first
}

readFirst values: [Int] -> Int => values[0]

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    readFirst(values) => first
}

readOwnedFirst values: [Int; ~] -> Int => values[0]

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    values -> readOwnedFirst => first
}

withFallback fallback: Int, values: [Int] -> Int => fallback + values[0]

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    0 -> withFallback(values) => first
}

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    values -> fold 0 total, item { total + item } => sum
}

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    values -> each item { item -> println }
}

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    values[0] => first
    values -> append(3) => grown
}

main {
    [1, 2; ~] => values!
    values! -> capacity => allocated
    values! -> push(3)
    values![0] => first
}

readScore scores: {Int: Int} -> Int => scores[1]

main {
    { 1: 2 } => scores
    scores -> readScore => first
}

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    true -> if {
        values[0] -> println
    } else {
        0 -> println
    }
}

main {
    true -> while {
        [1, 2; ~] => values
        values -> capacity => allocated
        values[0] => first
        break
    }
}

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    "value=$(values[0])" -> println
}

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    "value=$(values -> len)" -> println
}

readFirst values: [Int] -> Int => values[0]

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    "value=$(values -> readFirst)" -> println
}

main {
    [1, 2; ~] => values
    values -> capacity => allocated
    "value=$(values -> append(3) -> len)" -> println
